1	import { lazy, Suspense } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	
14	// Lazy-loaded route components for code splitting
15	const Index = lazy(() => import("./pages/Index"));
16	const Auth = lazy(() => import("./pages/Auth"));
17	const Admin = lazy(() => import("./pages/Admin"));
18	const Settings = lazy(() => import("./pages/Settings"));
19	const Profile = lazy(() => import("./pages/Profile"));
20	const Billing = lazy(() => import("./pages/Billing"));
21	const NotFound = lazy(() => import("./pages/NotFound"));
22	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
23	const BookDemo = lazy(() => import("./pages/BookDemo"));
24	const RequestFeature = lazy(() => import("./pages/RequestFeature"));
25	const Changelog = lazy(() => import("./pages/Changelog"));
26	const Apply = lazy(() => import("./pages/Apply"));
27	const LandingPage = lazy(() => import("@/components/LandingPage"));
28	
29	const queryClient = new QueryClient();
30	
31	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
32	const PageLoader = () => (
33	  <div className="flex h-svh w-full overflow-hidden">
34	    {/* Sidebar skeleton — matches sidebar width */}
35	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
36	      <div className="px-4 py-4">
37	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
38	      </div>
39	      <div className="border-t border-border" />
40	      <div className="p-3 space-y-2">
41	        {[1, 2, 3, 4].map((i) => (
42	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
43	        ))}
44	      </div>
45	    </div>
46	    {/* Content area skeleton */}
47	    <div className="flex-1 flex flex-col min-w-0">
48	      {/* Header skeleton */}
49	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
50	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
51	        <div className="flex items-center gap-3">
52	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
53	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
54	        </div>
55	      </div>
56	      {/* Body skeleton */}
57	      <div className="flex-1 overflow-y-auto p-6">
58	        <div className="max-w-5xl mx-auto space-y-4">
59	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
60	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
61	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
62	            {[1, 2, 3, 4].map((i) => (
63	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
64	            ))}
65	          </div>
66	        </div>
67	      </div>
68	    </div>
69	  </div>
70	);
71	
72	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
73	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
74	  const { isAdmin, loading } = useAuth();
75	
76	  // Don't block rendering while loading — only gate when we know maintenance is on
77	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
78	  return <>{children}</>;
79	};
80	
81	const RootRoute = () => {
82	  const { user, loading } = useAuth();
83	  if (loading) return <PageLoader />;
84	  return user ? <Index /> : <LandingPage />;
85	};
86	
87	const App = () => (
88	  <QueryClientProvider client={queryClient}>
89	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
90	      <AuthProvider>
91	        <TooltipProvider>
92	          <Sonner />
93	          <BrowserRouter>
94	            <SeoHead />
95	            <Suspense fallback={<PageLoader />}>
96	              <Routes>
97	                {/* Public apply page — outside MaintenanceGate so candidates can always apply */}
98	                <Route path="/apply/:jobId" element={<Apply />} />
99	                <Route path="*" element={
100	                  <MaintenanceGate>
101	                    <Routes>
102	                      <Route path="/auth" element={<Auth />} />
103	                      <Route path="/" element={<RootRoute />} />
104	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
105	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
106	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
107	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
108	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
109	                      <Route path="/book-demo" element={<BookDemo />} />
110	                      <Route path="/request-feature" element={<RequestFeature />} />
111	                      <Route path="/changelog" element={<Changelog />} />
112	                      <Route path="/payment/callback" element={<PaymentCallback />} />
113	                      <Route path="*" element={<NotFound />} />
114	                    </Routes>
115	                  </MaintenanceGate>
116	                } />
117	              </Routes>
118	            </Suspense>
119	            <ChatWidget />
120	          </BrowserRouter>
121	        </TooltipProvider>
122	      </AuthProvider>
123	    </ThemeProvider>
124	  </QueryClientProvider>
125	);
126	
127	export default App;
