1	import { useState } from "react";
2	import { Badge } from "@/components/ui/badge";
3	import { Button } from "@/components/ui/button";
4	import { Separator } from "@/components/ui/separator";
5	import { Sheet, SheetContent } from "@/components/ui/sheet";
6	import { ScrollArea } from "@/components/ui/scroll-area";
7	import { Phone, Mail, FileText, Archive, MapPin, Download, X } from "lucide-react";
8	import { toast } from "sonner";
9	import type { Result } from "@/pages/Index";
10	import type { HiringStage } from "@/hooks/useStageTracker";
11	
12	import CandidateSummary from "@/components/candidate/CandidateSummary";
13	import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
14	import ExperiencePanel from "@/components/candidate/ExperiencePanel";
15	import EducationPanel from "@/components/candidate/EducationPanel";
16	import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
17	import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
18	import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
19	import StageTracker from "@/components/candidate/StageTracker";
20	import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
21	
22	interface CandidateDetailSheetProps {
23	  result: Result | null;
24	  isOpen: boolean;
25	  onClose: () => void;
26	  jobId?: string | null;
27	  jobTitle?: string | null;
28	  formatCandidateName: (filename: string) => string;
29	  onDownload: (filePath: string, filename: string) => void;
30	  onDismiss: (resumeId: string) => void;
31	  currentStage?: HiringStage | null;
32	  stageUpdatedAt?: string | null;
33	  onStageChange?: (resumeId: string, stage: HiringStage) => void;
34	}
35	
36	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
37	  if (score >= 70) return { label: "Strong", variant: "success" };
38	  if (score >= 40) return { label: "Good", variant: "warning" };
39	  return { label: "Weak", variant: "destructive" };
40	};
41	
42	const CandidateDetailSheet = ({
43	  result: r,
44	  isOpen,
45	  onClose,
46	  jobId,
47	  jobTitle,
48	  formatCandidateName,
49	  onDownload,
50	  onDismiss,
51	  currentStage,
52	  stageUpdatedAt,
53	  onStageChange,
54	}: CandidateDetailSheetProps) => {
55	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
56	
57	  if (!r) return null;
58	
59	  const strength = getStrengthLabel(r.overall_score);
60	  const candidateName = r.candidate_name || formatCandidateName(r.filename);
61	
62	  return (
63	    <>
64	      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
65	        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden">
66	          {/* Dark hero header */}
67	          <div className="bg-foreground text-background px-6 pt-6 pb-5 shrink-0 relative">
68	            <button onClick={onClose} className="absolute top-4 right-4 rounded-sm opacity-70 hover:opacity-100 transition-opacity">
69	              <X className="h-4 w-4" />
70	            </button>
71	
72	            <div className="space-y-3">
73	              <div>
74	                <h2 className="text-xl font-semibold truncate pr-8">{candidateName}</h2>
75	                <div className="flex items-center gap-2 mt-1 flex-wrap text-background/60">
76	                  {r.candidate_location && (
77	                    <span className="flex items-center gap-1 text-xs">
78	                      <MapPin className="h-3 w-3" /> {r.candidate_location}
79	                    </span>
80	                  )}
81	                  {r.candidate_email && <span className="text-xs">{r.candidate_email}</span>}
82	                </div>
83	              </div>
84	
85	              {/* Score + badge row */}
86	              <div className="flex items-end gap-4">
87	                <div>
88	                  <span className="text-xs text-background/50 block">Overall Match</span>
89	                  <span className="text-4xl font-bold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
90	                </div>
91	                <div className="flex items-center gap-2 pb-1.5">
92	                  <Badge variant={strength.variant} className="shadow-sm">{strength.label}</Badge>
93	                  {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
94	                  {r.confidence ? <Badge variant="outline" className="text-background/70 border-background/20">{r.confidence}% confidence</Badge> : null}
95	                </div>
96	              </div>
97	
98	              {/* Progress bar */}
99	              <div className="h-1.5 rounded-full bg-background/20 overflow-hidden">
100	                <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
101	              </div>
102	            </div>
103	          </div>
104	
105	          {/* Action buttons */}
106	          <div className="px-6 py-3 flex items-center gap-2 border-b border-border shrink-0 bg-muted/30">
107	            {r.candidate_phone && (
108	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
109	                onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
110	                <Phone className="h-3 w-3" /> Call
111	              </Button>
112	            )}
113	            {r.candidate_email && (
114	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
115	                onClick={() => setEmailDialogOpen(true)}>
116	                <Mail className="h-3 w-3" /> Email
117	              </Button>
118	            )}
119	            {r.file_path && (
120	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
121	                onClick={() => onDownload(r.file_path!, r.filename)}>
122	                <Download className="h-3 w-3" /> Resume
123	              </Button>
124	            )}
125	            <div className="ml-auto">
126	              <Button variant="ghost" size="sm" className="h-8 gap-1.5 text-xs text-muted-foreground hover:text-destructive"
127	                onClick={() => { onDismiss(r.resume_id); onClose(); }}>
128	                <Archive className="h-3 w-3" /> Archive
129	              </Button>
130	            </div>
131	          </div>
132	
133	          {/* Scrollable panels */}
134	          <div className="relative flex-1 min-h-0">
135	            <ScrollArea className="h-full">
136	              <div className="px-6 py-6 space-y-6">
137	                {/* 1. Stage — where is this candidate in the pipeline? */}
138	                {onStageChange && (
139	                  <StageTracker
140	                    currentStage={currentStage || "applied"}
141	                    updatedAt={stageUpdatedAt}
142	                    onStageChange={(stage) => onStageChange(r.resume_id, stage)}
143	                  />
144	                )}
145	
146	                {/* 2. JD Alignment — the hiring decision: fit or not? */}
147	                <JDAlignedPanel result={r} />
148	
149	                {/* 3. Summary — AI's take on this candidate */}
150	                <CandidateSummary result={r} />
151	
152	                {/* 4. Strengths & Gaps — quick signal */}
153	                <StrengthsGapsPanel result={r} />
154	
155	                {/* 5. Skills — technical depth */}
156	                <SkillsDetailPanel result={r} />
157	
158	                {/* 6. Background — experience + education */}
159	                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
160	                  <ExperiencePanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves as string[]} />
161	                  <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
162	                </div>
163	
164	                {/* 7. Interview prep — last, for next steps */}
165	                <InterviewQuestionsPanel result={r} />
166	              </div>
167	            </ScrollArea>
168	            <div className="absolute bottom-0 left-0 right-0 h-8 bg-gradient-to-t from-background to-transparent pointer-events-none" />
169	          </div>
170	        </SheetContent>
171	      </Sheet>
172	
173	      {r.candidate_email && (
174	        <EmailOutreachDialog
175	          open={emailDialogOpen}
176	          onOpenChange={setEmailDialogOpen}
177	          candidateName={candidateName}
178	          candidateEmail={r.candidate_email}
179	          jobTitle={jobTitle || "Open Position"}
180	          matchScore={Math.round(r.overall_score ?? 0)}
181	          resumeId={r.resume_id}
182	          jobId={jobId || ""}
183	        />
184	      )}
185	    </>
186	  );
187	};
188	
189	export default CandidateDetailSheet;
190	
