16	  title: string;
17	  message: string;
18	  read: boolean;
19	  created_at: string;
20	  metadata?: Record<string, any>;
21	}
22	
23	const ICON_MAP: Record<Notification["type"], { icon: typeof Bell; color: string; bg: string }> = {
24	  ranking_complete: { icon: CheckCircle2, color: "text-emerald-600", bg: "bg-emerald-100" },
25	  ranking_failed: { icon: AlertCircle, color: "text-destructive", bg: "bg-destructive/10" },
26	  credits_low: { icon: Coins, color: "text-amber-600", bg: "bg-amber-100" },
27	  credits_added: { icon: Coins, color: "text-blue-600", bg: "bg-blue-100" },
28	  system: { icon: Info, color: "text-muted-foreground", bg: "bg-muted" },
29	};
30	
31	// ─── Component ──────────────────────────────────────────────────────────────
32	
33	const NotificationBell = () => {
34	  const { user } = useAuth();
35	  const [open, setOpen] = useState(false);
36	  const [notifications, setNotifications] = useState<Notification[]>([]);
37	  const [loading, setLoading] = useState(false);
38	
39	  const unreadCount = notifications.filter((n) => !n.read).length;
40	
41	  const fetchNotifications = useCallback(async () => {
42	    if (!user) return;
43	    setLoading(true);
44	    try {
45	      const { data } = await supabase
46	        .from("notifications")
47	        .select("id, type, title, message, read, created_at, metadata")
48	        .eq("user_id", user.id)
49	        .order("created_at", { ascending: false })
50	        .limit(20);
51	      if (data) setNotifications(data as Notification[]);
52	    } catch {
53	      // Silently fail — notifications are non-critical
54	    } finally {
55	      setLoading(false);
56	    }
57	  }, [user]);
58	
59	  // Initial fetch for badge count
60	  useEffect(() => {
61	    fetchNotifications();
62	  }, [fetchNotifications]);
63	
64	  // Refresh when popover opens
65	  useEffect(() => {
66	    if (open) fetchNotifications();
67	  }, [open, fetchNotifications]);
68	
69	  // Real-time subscription for new notifications
70	  useEffect(() => {
71	    if (!user) return;
72	
73	    const channel = supabase
74	      .channel("notifications")
75	      .on(
76	        "postgres_changes",
77	        {
78	          event: "INSERT",
79	          schema: "public",
80	          table: "notifications",
81	          filter: `user_id=eq.${user.id}`,
82	        },
83	        (payload) => {
84	          setNotifications((prev) => [payload.new as Notification, ...prev].slice(0, 20));
85	        }
86	      )
87	      .subscribe();
88	
89	    return () => {
90	      supabase.removeChannel(channel);
91	    };
92	  }, [user?.id]);
93	
94	  const markAsRead = async (id: string) => {
95	    setNotifications((prev) =>
96	      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
97	    );
98	    await supabase.from("notifications").update({ read: true }).eq("id", id);
99	  };
100	
101	  const markAllAsRead = async () => {
102	    if (unreadCount === 0) return;
103	    const unreadIds = notifications.filter((n) => !n.read).map((n) => n.id);
104	    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
105	    await supabase.from("notifications").update({ read: true }).in("id", unreadIds);
106	  };
107	
108	  return (
109	    <Popover open={open} onOpenChange={setOpen}>
110	      <PopoverTrigger asChild>
111	        <button
112	          className="relative h-9 w-9 rounded-lg bg-muted flex items-center justify-center text-muted-foreground hover:text-foreground hover:bg-muted/80 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-1"
113	          aria-label={`Notifications${unreadCount > 0 ? ` (${unreadCount} unread)` : ""}`}
114	        >
115	          <Bell className="h-4 w-4" />
116	          {unreadCount > 0 && (
117	            <span className="absolute -top-0.5 -right-0.5 flex items-center justify-center min-w-[18px] h-[18px] px-1 rounded-full bg-primary text-primary-foreground text-[10px] font-bold leading-none shadow-sm">
118	              {unreadCount > 99 ? "99+" : unreadCount}
119	            </span>
120	          )}
121	        </button>
122	      </PopoverTrigger>
123	
124	      <PopoverContent align="end" className="w-80 p-0">
125	        {/* Header */}
126	        <div className="flex items-center justify-between px-4 pt-3.5 pb-3">
127	          <h3 className="text-sm font-semibold text-foreground">Notifications</h3>
128	          {unreadCount > 0 && (
129	            <button
130	              onClick={markAllAsRead}
131	              className="inline-flex items-center gap-1 text-[11px] font-medium text-primary hover:text-primary/80 transition-colors"
132	            >
133	              <CheckCheck className="h-3 w-3" />
134	              Mark all read
135	            </button>
136	          )}
137	        </div>
138	
139	        <Separator />
140	
141	        {/* Notification list */}
142	        <div className="max-h-[360px] overflow-y-auto">
143	          {loading && notifications.length === 0 ? (
144	            <div className="px-4 py-8 text-center">
145	              <div className="h-4 w-4 border-2 border-primary border-t-transparent rounded-full animate-spin mx-auto" />
146	              <p className="text-xs text-muted-foreground mt-2">Loading...</p>
147	            </div>
148	          ) : notifications.length === 0 ? (
149	            <div className="px-4 py-10 text-center">
150	              <Bell className="h-8 w-8 text-muted-foreground/30 mx-auto mb-2" />
151	              <p className="text-sm text-muted-foreground">No notifications yet</p>
152	              <p className="text-xs text-muted-foreground/70 mt-0.5">
153	                We'll notify you about job rankings and updates.
154	              </p>
155	            </div>
156	          ) : (
157	            notifications.map((notification) => {
158	              const style = ICON_MAP[notification.type] ?? ICON_MAP.system;
159	              const Icon = style.icon;
160	
161	              return (
162	                <button
163	                  key={notification.id}
164	                  onClick={() => markAsRead(notification.id)}
165	                  className={cn(
166	                    "w-full text-left px-4 py-3 flex gap-3 hover:bg-muted/50 transition-colors border-b border-border last:border-0",
167	                    !notification.read && "bg-primary/[0.03]"
168	                  )}
169	                >
170	                  <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5", style.bg)}>
171	                    <Icon className={cn("h-4 w-4", style.color)} />
172	                  </div>
173	                  <div className="min-w-0 flex-1">
174	                    <div className="flex items-start justify-between gap-2">
175	                      <p className={cn("text-sm leading-tight truncate", !notification.read ? "font-semibold text-foreground" : "font-medium text-foreground/80")}>
176	                        {notification.title}
177	                      </p>
178	                      {!notification.read && (
179	                        <span className="h-2 w-2 rounded-full bg-primary shrink-0 mt-1.5" />
180	                      )}
181	                    </div>
182	                    <p className="text-xs text-muted-foreground line-clamp-2 mt-0.5">
183	                      {notification.message}
184	                    </p>
185	                    <p className="text-[10px] text-muted-foreground/60 mt-1">
186	                      {formatDistanceToNow(new Date(notification.created_at), { addSuffix: true })}
187	                    </p>
188	                  </div>
189	                </button>
190	              );
191	            })
192	          )}
193	        </div>
194	      </PopoverContent>
195	    </Popover>
196	  );
197	};
198	
199	export default React.memo(NotificationBell);
